  "secrets.wall": "RELAIS CRAQUÉ\nVisez et tirez à la fissure éclatante.",
  "secrets.plates": "SECRET · PLAQUES DE PRESSION\n Étape 1 → 2 → 3: à gauche, à droite, au milieu.",
  "secrets.runes": "SECRET · BATTRE LES RUNES\nTirez à gauche, à droite, au milieu d'un chant.\nLes cubes d'or marquent le rythme, même s'ils sont muets.",
  "secrets.braziers": "SECRET · TROIS BRASIERS\nLes armes de feu allument les brasiers.\nNe tirez pas sur la plaque d'or, puis visez et tirez.",
  "secrets.ice": "SECRET · PASSAGE SURGELÉ\nGeler le cristal bleu, puis traverser l'eau.\nChargez sur la plaque d'or, puis tirez.",
