  "secrets.golden_title": "SECRET · LE COLLECTIONNEUR DES COLLECTIONNEURS",
  "secrets.shadow_title": "SECRET · VOTRE RÉFLEXION SE SOUVIENT",
  "secrets.skin": "Armure de relais Pixel",
  "secrets.skin_short": "Relais Pixel",
  "secrets.skin_condition": "Résolvez une pièce secrète ou découvrez l'ancien code directionnel.",
  "secrets.category": "SECRET",
  "secrets.lore_name": "Le Relais oublié",
  "secrets.developer_name": "Le quart de nuit",
  "secrets.lore": "L'équipe de maintenance a caché un atelier derrière un faux mur. Trois lampes se souviennent de l'ordre: gauche, droite, milieu. Chaque relais résolu envoie toujours un merci.",
  "secrets.developer_lore": "Une petite pièce pour tous ceux qui ont gardé les îles en marche. Le robot danse parce que quelqu'un est enfin revenu. Merci de jouer.",
  "secrets.king_lore": "Trois Goldbugs manquants ont réveillé leur roi. Sa couronne se souvient de chaque pièce volée. Regardez les anneaux d'atterrissage dorés. Continuez à bouger et regardez sa liquidation.",
  "secrets.shadow_lore": "SECRET : Une nuit impeccable laisse une réflexion derrière elle. Elle passe à travers vos modèles d'armes ; son pouvoir emprunté a des limites sûres. Continuez à bouger et à regarder sa liquidation.",
  "secrets.a_room": "Hors de la carte",
  "secrets.a_room_desc": "Résolvez une salle de relais secrète.",
  "secrets.a_king": "Vérification royale",
  "secrets.a_king_desc": "SECRET: Attrapez trois Goldbugs en une seule course, réveillez la statue d'or et battez le Roi d'Or.",
  "secrets.a_shadow": "Mieux que mon ombre",
  "secrets.a_shadow_desc": "SECRET : défaitez votre réflexion après une étape de nuit impeccable.",
  "secrets.a_code": "Vieille école",
  "secrets.a_code_desc": "Découvrez l'ancien code directionnel sur l'écran titre.",
