  "content.84fee1b908": "Lames transversales",
  "content.21f48f0714": "Les lames de croissant jumelées se croisent vers l'extérieur, puis se tranchent le long d'un chemin de retour incurvé.",
  "content.bceb0fd05d": "Bobines Tesla",
  "content.20e9db560e": "Des serpentins se jettent derrière vous. Ils zappent les ennemis à proximité et électrifient la ligne à la bobine précédente.",
  "content.3fa4624af4": "Essaim de missiles",
  "content.d5a30861d8": "Des ventilateurs de minuscules missiles homogénés dans une vague stupéfiante, de petites explosions saturent la foule.",
  "content.33308c454a": "Éclats prismatiques",
  "content.7b8ce4b3a3": "Les cristaux ricochet entre les ennemis. Chacun se divise en deux petits cristaux sur son premier coup.",
  "content.6ae4da1570": "Fouet laser",
  "content.dda58a2099": "CLIQUEZ À FEU : balayez une poutre flexible sur un grand arc. Chaque balançoire frappe un ennemi une fois.",
  "content.d20d4a8f64": "Tourelle de poche",
  "content.5191e9018c": "CLIQUEZ DROITE: déployez une sentinelle au curseur. Elle suit et tire sur les ennemis; placez un autre remplace le plus ancien.",
  "content.b2ecb120df": "Gale de verre",
  "content.1519201745": "FUSION des lames Crosswind + Prism Shards. Les lames du croissant éclatent en éclats de cristal tout en divisant les shards ricochet à travers la foule.",
  "content.1ded80863d": "Grille de cornets",
  "content.5085777882": "FUSION de Tesla Coils + Swarm Missiles. Une batterie de missiles électriques : les explosions micro-missiles sautent la foudre à travers les ennemis voisins tandis que les bobines gardent votre trace.",
  "content.7bd71968dd": "Cellule Riposte",
  "content.f9fa5592c1": "Slipstream",
  "content.b3b5901935": "Encore",
  "content.55bf66186a": "Capacitateur en espèces",
  "content.718a53f70a": "Deuxième main",
  "content.45ac1a13ab": "Siège d'éjection",
  "content.b9fe1a7ba3": "Jack dans la boîte",
  "content.907ba6a6a3": "Coeur",
  "content.f83f00dc6d": "Fleurs wallées",
  "content.d8eb186561": "Front froid",
  "content.aad40fcb8f": "Primeur de sang",
  "content.6d90bab333": "Dernier mot",
  "content.9b782f6760": "Feu de signalisation",
  "content.8006dda1a1": "Équipage de puits",
  "content.c834d3facb": "Contre-choeur",
  "content.a1471f3244": "Bonde de sang",
  "content.b725c5e5fe": "Garde des ailes",
  "content.dd10e5feed": "Ovation permanente",
  "content.1b913d3b3f": "Balayez un faisceau flexible à travers un grand arc. Chaque balançoire frappe un ennemi une fois.",
  "content.a0fe8c20b1": "Déployer une sentinelle au curseur. Il suit et tire les ennemis; placer un autre remplace le plus ancien.",
  "content.672418ed7d": "Parry: les coups gagnent +⟪0⟫ dégâts pour ⟪1⟫s. Mettez avant les multiplicateurs.",
  "content.9ec4a01350": "Dash parfait: Orbit et Trail frappent avec +⟪0⟫% de dégâts pour ⟪1⟫s.",
  "content.f6d86f700c": "Utilisez votre ultime: +⟪0⟫% de dégâts pour ⟪1⟫s.",
  "content.3347d5257c": "En cash in a combo: les coups gagnent +⟪0⟫ dégâts pour ⟪1⟫s. Pas de bonus d'or.",
  "content.73023179eb": "Après un rembobinage se termine : +⟪0⟫% de dégâts pour ⟪1⟫s.",
  "content.9f02fc66b3": "Survis à la sortie du mécha : +⟪0⟫% de dégâts pendant ⟪1⟫s, explosion d'éjection comprise.",
  "content.c21d055973": "Ouvrir la poitrine : un shock nova de ⟪0⟫m inflige des dommages ⟪1⟫.",
  "content.4796d804bf": "Dans le feu de tes Bottes ardentes : les coups de Feu et de Traînée infligent +⟪0⟫% de dégâts.",
  "content.1c57742cae": "Dans un rayon de ⟪0⟫m de couverture : Orbit et Area font +⟪1⟫% de dégâts.",
  "content.b1bbcf2021": "À ⟪0⟫m ou plus : les coups de Gel et de Chaîne infligent +⟪1⟫% de dégâts.",
  "content.a58a60981e": "Chaque hit +⟪0⟫ dégâts. Max vie x⟪1⟫. Mettre avant les multiplicateurs.",
  "content.5e37395e25": "Chaque frappe perd ⟪0⟫ dégâts, puis x⟪1⟫. Forts succès gagne; la commande compte.",
  "content.352a455638": "Tes Brûlures donnent aux alliés +⟪0⟫% de chances de critique contre cet ennemi (max d'équipe +⟪1⟫%).",
  "content.0836247367": "D'autres alliés dans les ⟪0⟫m rechargent toutes les armes ⟪1⟫% plus vite (cap d'équipe +⟪2⟫% de vitesse).",
  "content.e76459c2b5": "Un allié pare à moins de ⟪0⟫m : tu émets une nova de Choc de ⟪1⟫m infligeant ⟪2⟫ dégâts. Recharge : ⟪3⟫s.",
  "content.87006ad396": "Partage ⟪0⟫% des soins réellement reçus grâce à tes éliminations avec chaque allié à moins de ⟪1⟫m (max ⟪2⟫%).",
  "content.5cb95a9e84": "Un allié fait une esquive parfaite à moins de ⟪0⟫m : tu gagnes ⟪1⟫s d'invulnérabilité (max ⟪2⟫s). Recharge : ⟪3⟫s.",
  "content.07d6955765": "Un allié utilise un maximum de ⟪0⟫m : votre offre de succès +⟪1⟫% de dégâts pour ⟪2⟫s.",
  "content.7042a34e52": "Récipients de gale",
  "content.4147d8d8ce": "Six énormes croissants ont encore frappé à leur retour.",
  "content.17445c9856": "LAMES DE VENT CROISÉ MAX + PROPULSEURS À RÉACTION",
  "content.e8a4b67f4f": "Grille de tonnerre",
  "content.3c22ee344d": "Six bobines à longue portée tissent une clôture éclair rapide.",
  "content.7c2b3d0cd9": "BOBINES MAX TESLA + BATTERIE",
  "content.0551ec041f": "Armada Hornet",
  "content.ef5520301e": "Quatorze frelons rapides à tête chercheuse jaillissent en une vague continue.",
  "content.7254961088": "MISSILES D'ESSAIM MAX + CELLULE DE PUISSANCE",
  "content.c00761a1fb": "Kaléidoscope",
  "content.713510f70b": "Quatre cristaux ricochetent six fois et se divisent en plus petits durs.",
  "content.3f02a91752": "ÉCLATS PRISMATIQUES AU MAX + BALLES CRYO",
  "content.7eec71fe00": "Coup de soleil",
  "content.173f69c5f1": "Un large fouet brûlant (incendie), +40 degrés et 25% de dégâts.",
  "content.74236350d1": "ÉVOLUTION DU FOUET DE BEAM",
  "content.bee03eb48f": "Choux-croûte",
  "content.c3d026a983": "Un second fouet balaye derrière vous, les deux ennemis de choc.",
  "content.8847d2f7b5": "Sentinelle du glacier",
  "content.c1de1b50b7": "Larges boulons de givre percer 2 ennemis. +20% endommagement.",
  "content.c2234f7ae0": "ÉVOLUTION DES SENTINELLES DE POCHE",
