  "text.the_team_shares_lives_per_stage_downed_and_nobod_f17749": "L'équipe partage ⟪0⟫ vies (+⟪1⟫ par étape). Downed et personne ne vient? Rachète avec l'or de tout le monde.",
  "text.open_a38bd5": "OUVERT",
