  "text.starfall_ab516b": "Pluie d'étoiles",
  "text.stars_fall_on_the_biggest_crowds_near_you_and_ex_3e6323": "Les étoiles tombent sur les plus grandes foules près de vous et explosent.",
  "text.calls_2_falling_stars_onto_the_biggest_crowds_ne_7d582c": "2 étoiles tombent sur les plus grandes foules à proximité.",
  "text.heavier_stars_24a27b": "Des étoiles lourdes.",
