  "text.5_stars_that_each_burst_into_3_more_on_impact_492475": "5 étoiles dont chacune éclate en 3 autres à l'impact.",
  "text.turbo_trouble_5fd421": "Turbo Trouble",
  "text.enemies_move_at_double_speed_a44e8e": "Les ennemis se déplacent à double vitesse.",
  "text.right_on_time_4f995a": "Juste à l'heure",
  "text.no_left_click_weapon_use_your_right_click_and_sp_8ad679": "Pas d'arme à clic gauche. Utilisez votre clic droit et spécial!",
  "text.elite_parade_cfcb04": "Parade Elite",
  "text.every_normal_director_spawn_is_an_elite_5969da": "Chaque metteur en scène normal est une élite.",
  "text.one_hit_wonder_e75450": "Un seul coup de foudre",
  "text.any_unblocked_hit_is_lethal_revives_still_work_ea75a7": "Tout coup non bloqué est mortel.",
  "text.bullet_carnival_8737a1": "Carnaval des balles",
  "text.enemy_shots_travel_twice_as_fast_8e413e": "Les tirs ennemis voyagent deux fois plus vite.",
  "text.level_up_5b0ee6": "NIVEAU SUPÉRIEUR !",
  "text.pick_1_of_3_cards_click_or_keys_1_3_the_ribbon_a_c71357": "Choisissez 1 de 3 cartes (cliquez, ou touches 1-3). Le ruban en bas indique ce qu'il met à niveau : CLIQUEZ À MOINS, CLIQUEZ À DROITE, SPÉCIAL, AUTO-OUVERTURE OU POINT.",
  "text.evolution_fork_634218": "CHOIX D'ÉVOLUTION",
  "text.enough_ranks_to_evolve_pick_one_of_the_two_forms_2fd106": "Suffisamment de rangs pour évoluer! Choisissez UN des deux formulaires. Chaque changement de la façon dont l'article fonctionne et ajoute une balise que le nouveau Mods peut activer.",
  "text.the_shop_37cbe7": "LA BOUTIQUE",
  "text.mods_sit_in_5_slots_and_change_how_your_damage_w_71e69c": "Mods asseoir dans 5 fentes et changer comment vos dommages fonctionne. L'or que vous gardez gagne des intérêts à chaque étape clair, afin d'économiser peut payer.",
  "text.mod_order_matters_7598df": "L'ORDRE DES MODS COMPTE",
  "text.damage_flows_through_your_mods_left_to_right_dam_1e221f": "Les dommages passent par votre Mods À DROITE : (dommage + ajoute) x mults. Déplacez à plat \"+dommage\" Mods avant \"x dommage\" avec les flèches. Echo copie la Mod à sa droite.",
  "text.elite_07576c": "ELITE !",
  "text.a_big_tough_enemy_with_a_modifier_shield_fast_sp_891aa6": "Un grand et dur ennemi avec un modificateur (bouclier, rapide, scission...). Sa barre de crâne montre sa vie. Battez-la pour un coffre au trésor.",
  "text.exposed_e6c328": "VULNÉRABLE",
  "text.right_click_hits_expose_enemies_30_damage_from_e_38bc87": "Le clic droit frappe les ennemis d'Expose : +30% de dégâts de tout le monde pendant 4 s. Ouvrez avec le clic droit, terminez avec le gauche.",
  "text.burn_ticks_damage_shock_makes_enemies_take_20_fr_22dfd5": "Brûler les dommages tiques, Shock fait prendre aux ennemis +20%, Gelez les arrête. Mettre deux sur le même ennemi pour un combo.",
  "text.status_combo_f68922": "COMBO D'ÉTAT !",
  "text.burn_shock_overload_blast_kill_a_frozen_enemy_sh_c6ed94": "Brûler + Choc = explosion d'overload. Tuer un ennemi congelé = SHATTER. Une explosion sur un ennemi brûlant = NAPALM. Mods peut rendre chacun plus fort.",
  "text.it_changes_its_attacks_at_66_and_33_life_red_zon_bf37e5": "Ses attaques changent à 66% et 33% de vie. Les zones et lignes rouges annoncent le danger : esquive à travers (⟪0⟫) ou pare les tirs (⟪1⟫).",
  "text.treasure_chest_81663c": "COFFRE AU TRÉSOR",
  "text.walk_into_it_for_a_free_item_on_the_spot_the_arr_3230d7": "Marchez dedans pour un objet libre sur place. La flèche au bord de l'écran pointe vers le point le plus proche.",
  "text.special_ready_f6a478": "PRÊTE SPÉCIALE",
  "text.press_or_middle_click_for_your_special_it_rechar_03aa5b": "Appuyez sur ⟪0⟫ (ou le clic moyen) pour votre spécial. Il se recharge au fil du temps.",
  "text.ultimate_ready_d08f2b": "PRÊTE ULTIME",
  "text.press_perfect_dodges_parries_and_kills_charge_yo_916d6b": "Appuyez sur ⟪0⟫! Parfaites dodges, parries et tue chargez l'ultime de votre héros.",
  "text.style_meter_8e60e9": "COMPTEUR DE STYLE",
  "text.fast_kills_perfect_dodges_and_parries_raise_your_9b344a": "Des tueries rapides, des dodges et des parries parfaites font passer votre style de D à SS. Un style plus élevé donne plus de score et XP.",
  "text.gear_f7f969": "ROUAGE",
  "text.each_gear_rerolls_one_set_of_level_up_cards_on_t_5e783d": "Chaque engrenage reroule un jeu de cartes de niveau (⟪0⟫ sur l'écran de niveau).",
  "text.stage_clear_4e29fa": "NIVEAU TERMINÉ",
  "text.walk_into_the_portal_for_the_next_stage_every_st_adf1cd": "Entre dans le portail pour passer à la zone suivante. La difficulté augmente à chaque zone et chaque 4e zone se termine par le boss final.",
  "text.a_teammate_revives_you_by_standing_next_to_you_f_b91da8": "Un coéquipier vous ravive en vous tenant à côté de vous pendant 3 s. Cliquez pour regarder un autre coéquipier pendant ce temps.",
  "text.teammate_down_47afc6": "ALLIÉ À TERRE",
  "text.stand_next_to_them_for_3_s_to_revive_them_you_bo_80d4d7": "Tenez-vous à côté d'eux pendant 3 s pour les ranimer. Vous obtenez tous deux un moment d'invincibilité.",
  "text.walk_around_with_or_the_left_stick_you_always_fa_4087eb": "Marchez avec ⟪0⟫ ⟪1⟫ ⟪2⟫ ⟪3⟫ ou le bâton gauche. Vous faites toujours face où vous visez.",
  "text.aim_and_fire_e2180c": "BUT ET FEU",
  "text.aim_with_the_mouse_or_right_stick_and_hold_left__395851": "Vise avec la souris ou le stick droit et maintiens le CLIC GAUCHE pour tirer avec ⟪0⟫. Détruis les ⟪1⟫ robots cibles.",
  "text.hold_right_click_or_x_for_your_its_hits_expose_e_c35ec0": "Tenez à droite CLIQUEZ (ou X) pour votre ⟪0⟫. Ses coups EXPOSent les ennemis: +30% de dégâts de tout le monde pour 4 s. Exposez le gros robot.",
  "text.press_to_dash_you_can_t_be_hit_mid_dash_dash_thr_ff9c38": "Appuyez sur ⟪0⟫ pour le tiret: vous ne pouvez pas être frappé mi-dash. Dash TROUGH un tir rose juste avant qu'il vous frappe.",
  "text.press_or_b_right_as_a_pink_shot_reaches_you_to_p_99aaf3": "Appuyez sur ⟪0⟫ (ou B) dès qu'un tir rose vous parvient à PARRY le dos au tireur.",
  "text.your_special_is_ready_press_or_rb_to_set_off_you_fa2e3b": "Votre spécial est prêt : appuyez sur ⟪0⟫ (ou RB) pour lancer votre ⟪1⟫ à côté des robots. Il se recharge au fil du temps.",
  "text.ultimate_df1d2d": "ULTIME",
  "text.perfect_dodges_parries_and_kills_charge_your_her_5caa68": "Perfect dodges, parries et tue chargez l'ULTIMATE de votre héros. Il est plein: appuyez sur ⟪0⟫ (ou R3).",
  "text.level_up_529820": "NIVEAU SUPÉRIEUR",
  "text.kills_drop_xp_gems_that_fly_to_you_a_full_xp_bar_8d848d": "Une barre pleine de XP est un niveau-up: choisissez l'une des 3 cartes. Le ruban dit ce qu'il met à niveau.",
  "text.chests_pop_up_on_the_map_every_30_s_the_arrow_at_2bf388": "Les poitrines apparaissent sur la carte toutes les 30 s (la flèche au bord de l'écran leur pointe). Marchez dans celui-ci pour un article gratuit.",
