  "text.a_flash_flood_mid_fight_you_just_swam_through_it_97a1f1": "Tu viens de nager !",
  "text.the_whole_island_split_in_two_and_you_did_not_ev_b93dd5": "Toute l'île s'est divisée en deux, et tu n'as même pas cligné !",
